package org.apache.commons.math.optimization.univariate;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Comparator;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.exception.ConvergenceException;
import org.apache.commons.math.exception.FunctionEvaluationException;
import org.apache.commons.math.exception.MathIllegalStateException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.optimization.ConvergenceChecker;
import org.apache.commons.math.optimization.GoalType;
import org.apache.commons.math.optimization.univariate.GoalType.MAXIMIZE;
import org.apache.commons.math.optimization.univariate.GoalType.MINIMIZE;
import org.apache.commons.math.random.RandomGenerator;
import org.apache.commons.math.util.FastMath;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class MultiStartUnivariateRealOptimizer_optimize_TriageGen2Test {

    private BaseUnivariateRealOptimizer<UnivariateRealFunction> mockOptimizer;
    private MultiStartUnivariateRealOptimizer optimizer;
    private final int starts = 3;

    @Before
    public void setUp() {
        mockOptimizer = mock(BaseUnivariateRealOptimizer.class);
        // Using a fixed seed or default generator via constructor
        optimizer = new MultiStartUnivariateRealOptimizer(mockOptimizer, starts, new org.apache.commons.math.random.JDKRandomGenerator());
    }

    @Test
    public void testOptimizeMinimization() throws FunctionEvaluationException {
        // Arrange
        UnivariateRealFunction function = x -> Math.pow(x - 2, 2);
        double min = 0.0;
        double max = 5.0;
        UnivariateRealPointValuePair expectedResult = new ArrayUnivariateRealPointValuePair(2.0, 0.0);

        when(mockOptimizer.optimize(org.mockito.ArgumentMatchers.any(), 
                                    org.mockito.ArgumentMatchers.eq(MINIMIZE), 
                                    org.mockito.ArgumentMatchers.eq(min), 
                                    org.mockito.ArgumentMatchers.eq(max), 
                                    org.mockito.ArgumentMatchers.anyDouble()))
            .thenReturn(expectedResult);

        // Act
        UnivariateRealPointValuePair result = optimizer.optimize(function, MINIMIZE, min, max);

        // Assert
        assertNotNull(result);
        assertEquals(2.0, result.getPoint(), 1e-10);
        assertEquals(0.0, result.getValue(), 1e-10);
    }

    @Test
    public void testOptimizeMaximization() throws FunctionEvaluationException {
        // Arrange
        UnivariateRealFunction function = x -> -(Math.pow(x - 3, 2));
        double min = 0.0;
        double max = 10.0;
        UnivariateRealPointValuePair expectedResult = new ArrayUnivariateRealPointValuePair(3.0, 0.0);

        when(mockOptimizer.optimize(org.mockito.ArgumentMatchers.any(), 
                                    org.mockito.ArgumentMatchers.eq(MAXIMIZE), 
                                    org.mockito.ArgumentMatchers.eq(min), 
                                    org.mockito.ArgumentMatchers.eq(max), 
                                    org.mockito.ArgumentMatchers.anyDouble()))
            .thenReturn(expectedResult);

        // Act
        UnivariateRealPointValuePair result = optimizer.optimize(function, MAXIMIZE, min, max);

        // Assert
        assertNotNull(result);
        assertEquals(3.0, result.getPoint(), 1e-10);
        assertEquals(0.0, result.getValue(), 1e-10);
    }

    @Test(expected = FunctionEvaluationException.class)
    public void testOptimizeThrowsException() throws FunctionEvaluationException {
        // Arrange
        UnivariateRealFunction function = x -> {
            throw new FunctionEvaluationException(new RuntimeException("Evaluation failed"));
        };
        double min = 0.0;
        double max = 5.0;

        // We simulate the optimizer throwing the exception when called
        when(mockOptimizer.optimize(org.mockito.ArgumentMatchers.any(), 
                                    org.mockito.ArgumentMatchers.any(), 
                                    org.mockito.ArgumentMatchers.anyDouble(), 
                                    org.mockito.ArgumentMatchers.anyDouble(), 
                                    org.mockito.ArgumentMatchers.anyDouble()))
            .thenThrow(new FunctionEvaluationException(new RuntimeException("Failure")));

        // Act
        optimizer.optimize(function, MINIMIZE, min, max);
    }

    /**
     * Helper class to satisfy the return type requirement for testing
     */
    private static class ArrayUnivariateRealPointValuePair implements UnivariateRealPointValuePair {
        private final double point;
        private final double value;

        ArrayUnivariateRealPointValuePair(double point, double value) {
            this.point = point;
            this.value = value;
        }

        @Override
        public double getPoint() { return point; }

        @Override
        public double getValue() { return value; }
    }
}
